CREATE OR REPLACE FUNCTION public.strip_decor(text) RETURNS text LANGUAGE sql IMMUTABLE PARALLEL SAFE STRICT AS $fn$ SELECT btrim(regexp_replace($1, '[[:space:]]*[◉●✦★☆¹²³⁴ᴿᴬᵂᵛᶦᵖ]+[[:space:]]*$', '')) $fn$;--> statement-breakpoint
CREATE OR REPLACE FUNCTION public.channel_quality(text) RETURNS text LANGUAGE sql IMMUTABLE PARALLEL SAFE STRICT AS $fn$ SELECT upper(replace((regexp_match(public.strip_decor($1), '[[:space:]]+[[(]?(FHD|UHD|HD|SD|HEVC|H\.?265|H\.?264|4K|8K|2160P|1080P|720P|576P|480P|ᴴᴰ)[])]?[[:space:]]*$', 'i'))[1], 'ᴴᴰ', 'HD')) $fn$;--> statement-breakpoint
CREATE OR REPLACE FUNCTION public.quality_rank(text) RETURNS integer LANGUAGE sql IMMUTABLE PARALLEL SAFE STRICT AS $fn$ SELECT CASE public.channel_quality($1) WHEN 'FHD' THEN 0 WHEN '1080P' THEN 0 WHEN 'HD' THEN 1 WHEN '720P' THEN 1 WHEN 'H264' THEN 1 WHEN 'H.264' THEN 1 WHEN 'UHD' THEN 3 WHEN '4K' THEN 3 WHEN '8K' THEN 3 WHEN '2160P' THEN 3 WHEN 'SD' THEN 4 WHEN '576P' THEN 4 WHEN '480P' THEN 4 WHEN 'HEVC' THEN 5 WHEN 'H265' THEN 5 WHEN 'H.265' THEN 5 ELSE 2 END $fn$;--> statement-breakpoint
CREATE OR REPLACE FUNCTION public.channel_lang(text) RETURNS text LANGUAGE sql IMMUTABLE PARALLEL SAFE STRICT AS $fn$ SELECT upper(coalesce((regexp_match($1, '^[[:space:]]*([A-Za-z]{2,8})[[:space:]]*[-|]'))[1], '')) $fn$;--> statement-breakpoint
CREATE OR REPLACE FUNCTION public.channel_key(text) RETURNS text LANGUAGE sql IMMUTABLE PARALLEL SAFE STRICT AS $fn$ SELECT public.channel_lang($1) || '|' || public.normalize_name(btrim(regexp_replace(regexp_replace(public.strip_decor(regexp_replace($1, '^[[:space:]]*[A-Za-z]{2,8}[[:space:]]*[-|][[:space:]]*', '')), '[[:space:]]+[[(]?(FHD|UHD|HD|SD|HEVC|H\.?265|H\.?264|4K|8K|2160P|1080P|720P|576P|480P|ᴴᴰ)[])]?[[:space:]]*$', '', 'i'), '[[:space:]]+', ' ', 'g'), ' -')) $fn$;--> statement-breakpoint
CREATE OR REPLACE FUNCTION public.group_key(public.stream_type, text) RETURNS text LANGUAGE sql IMMUTABLE PARALLEL SAFE STRICT AS $fn$ SELECT CASE WHEN $1 = 'live'::public.stream_type THEN 'c|' || public.channel_key($2) ELSE 'w|' || public.work_key($2) END $fn$;--> statement-breakpoint
ALTER TABLE "streams" ADD COLUMN "group_key" text GENERATED ALWAYS AS (public.group_key(type, name)) STORED;--> statement-breakpoint
ALTER TABLE "streams" ADD COLUMN "quality_rank" integer GENERATED ALWAYS AS (public.quality_rank(name)) STORED;--> statement-breakpoint
CREATE INDEX "streams_group_idx" ON "streams" USING btree ("type","group_key","lang_rank","quality_rank","id");
